  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `session_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `revoked` TINYINT(1) NOT NULL DEFAULT 0,
